```java
// WRONG: authentication and authorization mixed into one method
public String handle(String user, String pass, String path) {
    if (!user.equals("admin") || !pass.equals("secret")) {
        return "401"; // identity check (authentication)
    }
    if (!path.equals("/reports")) {
        return "403"; // permission check tangled into the same place
    }
    return "OK";
}
```
Mixing the two makes the rules impossible to reuse and easy to get wrong.

```java
// RIGHT: Spring Security keeps authentication and authorization separate
@Bean
SecurityFilterChain chain(HttpSecurity http) throws Exception {
    return http
        .httpBasic(Customizer.withDefaults())            // authentication: who are you?
        .authorizeHttpRequests(auth -> auth             // authorization: what can you do?
            .requestMatchers("/reports").hasRole("ADMIN")
            .anyRequest().authenticated())
        .build();
}
```
Identity is verified once, then each request is authorized against declarative rules.

// JPA entity - pure persistence concern
@Entity
public class User {
    @Id
    private Long id;
    private String username;
    private String passwordHash;
    private boolean enabled;
    @ElementCollection(fetch = FetchType.EAGER)
    private Set<String> roles;
}

// UserDetails adapter - bridges User to Spring Security
public class CustomUserDetails implements UserDetails {
    private final User user;

    public CustomUserDetails(User user) {
        this.user = user;
    }

    @Override
    public Collection<? extends GrantedAuthority> getAuthorities() {
        return user.getRoles().stream()
            .map(role -> new SimpleGrantedAuthority("ROLE_" + role))
            .toList();
    }

    @Override
    public String getPassword() {
        return user.getPasswordHash();
    }

    @Override
    public String getUsername() {
        return user.getUsername();
    }

    @Override
    public boolean isEnabled() {
        return user.isEnabled();
    }

    @Override
    public boolean isAccountNonExpired() {
        return true; // implement if you track expiration
    }

    @Override
    public boolean isAccountNonLocked() {
        return true; // implement if you track locking
    }

    @Override
    public boolean isCredentialsNonExpired() {
        return true; // implement if passwords expire
    }
}

