// WRONG: plain-text password saved straight to the database
public void register(String username, String rawPassword) {
    User user = new User(username, rawPassword, "ROLE_USER");
    userRepository.save(user); // a single breach exposes every password
}
```
If the database leaks, every account is instantly compromised.

```java
// RIGHT: hash with BCrypt before storing
public void register(String username, String rawPassword) {
    String hash = passwordEncoder.encode(rawPassword); // salted BCrypt hash
    User user = new User(username, hash, "ROLE_USER");
    userRepository.save(user); // only the irreversible hash is stored
}
```
At login you verify with passwordEncoder.matches(raw, storedHash) — you never decrypt.

@Service
public class UserService {

    private final UserRepository userRepository;
    private final PasswordEncoder passwordEncoder;  // Injected by Spring

    public UserService(UserRepository userRepository, PasswordEncoder passwordEncoder) {
        this.userRepository = userRepository;
        this.passwordEncoder = passwordEncoder;
    }

    public void registerUser(String username, String rawPassword) {
        var hashedPassword = passwordEncoder.encode(rawPassword);  // BCrypt hash with salt
        var user = new User(username, hashedPassword, "ROLE_USER");
        userRepository.save(user);  // Store hash, never raw password
    }

    public boolean authenticateUser(String username, String rawPassword) {
        var user = userRepository.findByUsername(username)
            .orElseThrow(() -> new UsernameNotFoundException("User not found"));
        return passwordEncoder.matches(rawPassword, user.getPassword());  // Verify against stored hash
    }
}

@Configuration
public class SecurityConfig {

    @Bean
    public PasswordEncoder passwordEncoder() {
        return new BCryptPasswordEncoder(12);  // Strength 12 is good balance for 2024 hardware
    }
}

@Service
public class CustomUserDetailsService implements UserDetailsService {
    @Autowired
    private UserRepository userRepository;

    @Override
    public UserDetails loadUserByUsername(String username) {
        var user = userRepository.findByUsername(username)
            .orElseThrow(() -> new UsernameNotFoundException("User not found"));

        // Convert role strings to GrantedAuthority objects
        var authorities = user.getRoles().stream()
            .map(role -> new SimpleGrantedAuthority("ROLE_" + role))
            .toList();

        return new org.springframework.security.core.userdetails.User(
            user.getUsername(),
            user.getPasswordHash(),
            authorities // List<GrantedAuthority> passed here
        );
    }
}

@Configuration
@EnableWebSecurity
public class SecurityConfig {
    @Bean
    public SecurityFilterChain filterChain(HttpSecurity http) throws Exception {
        return http
            .authorizeHttpRequests(auth -> auth
                .requestMatchers("/api/admin/**").hasRole("ADMIN") // checks ROLE_ADMIN
                .requestMatchers("/api/user/**").hasAuthority("ROLE_USER") // explicit string
                .requestMatchers("/api/public/**").permitAll()
            )
            .build();
    }
}

@RestController
@RequestMapping("/api/orders")
public class OrderController {
    @Autowired
    private OrderService orderService;

    @PostMapping
    public ResponseEntity<Order> createOrder(@RequestBody OrderRequest request) {
        // No need to pass user info - service layer can access it
        var order = orderService.createOrder(request);
        return ResponseEntity.ok(order);
    }
}

@Service
public class OrderService {
    @Autowired
    private OrderRepository orderRepository;

    public Order createOrder(OrderRequest request) {
        // Get current authenticated user from SecurityContextHolder
        var authentication = SecurityContextHolder.getContext().getAuthentication();
        var username = authentication.getName();

        // Can also get full UserDetails if needed
        var userDetails = (UserDetails) authentication.getPrincipal();

        var order = new Order();
        order.setUsername(username);
        order.setItem(request.item());
        order.setStatus("PENDING");

        return orderRepository.save(order);
    }

    public List<Order> getCurrentUserOrders() {
        var username = SecurityContextHolder.getContext()
            .getAuthentication()
            .getName();
        return orderRepository.findByUsername(username);
    }
}

@Configuration
@EnableWebSecurity
public class SecurityConfig {

    @Bean
    public SecurityFilterChain securityFilterChain(HttpSecurity http) throws Exception {
        http
            .csrf(csrf -> csrf.disable())  // Disable CSRF for stateless JWT APIs
            .authorizeHttpRequests(auth -> auth
                .requestMatchers("/api/auth/**").permitAll()  // Login endpoint public
                .requestMatchers("/api/admin/**").hasRole("ADMIN")
                .anyRequest().authenticated()  // All other endpoints require authentication
            )
            .sessionManagement(session -> session
                .sessionCreationPolicy(SessionCreationPolicy.STATELESS)  // No server-side sessions
            )
            .addFilterBefore(jwtAuthenticationFilter(), UsernamePasswordAuthenticationFilter.class);  // Custom JWT filter runs early
        return http.build();
    }

    @Bean
    public JwtAuthenticationFilter jwtAuthenticationFilter() {
        return new JwtAuthenticationFilter();  // Extracts JWT from Authorization header
    }
}
